('docdoom-early-meuse-battle', 'intermission = {\r\n	title = \"Early Meuse Battle\",\r\n\r\n	-- If you want the brigades to be locked in place after deployment\r\n	-- specify the initial movement delay duration here\r\n	-- Time is in seconds\r\n	brigadeInitialMovementTime = { days = 0, hours = 0, minutes = 0, seconds = 0 },\r\n\r\n	-- CP Ownerships\r\n	-- By default all CPs are reset to their original ownership,\r\n	-- to change this behavior specify one of:\r\n	--  default = \"none\" -- leaves the map alone\r\n	--  default = WWII_ENGLAND|WWII_FRANCE|WWII_GERMANY|WWII_CHINA\r\n	ownerships = {\r\n	 default = \"none\",\r\n	 uk = {\r\n		\"Armentieres\",\r\n		\"Avelgem\",\r\n		\"Avesnes\",\r\n		\"Bailleul\",\r\n		\"Bavay\",\r\n		\"Beaumont\",\r\n		\"Bergues\",\r\n		\"Berlaimont\",\r\n		\"Binche\",\r\n		\"Brakel\",\r\n		\"Cassel\",\r\n		\"Cerfontaine\",\r\n		\"Charleroi\",\r\n		\"Conde\",\r\n		\"Dunkerque\",\r\n		\"Flavion\",\r\n		\"Hastiere\",\r\n		\"Hazebrouck\",\r\n		\"La Bassee\",\r\n		\"LeQuesnoy\",\r\n		\"Leuze\",\r\n		\"Lille\",\r\n		\"Maubeuge\",\r\n		\"Merbes\",\r\n		\"Mettet\",\r\n		\"Mons\",\r\n		\"Namur\",\r\n		\"Orchies\",\r\n		\"Oudenaarde\",\r\n		\"Philipville\",\r\n		\"Profondeville\",\r\n		\"Ronse\",\r\n		\"Roubaix\",\r\n		\"Sambreville\",\r\n		\"Seclin\",\r\n		\"Somzee\",\r\n		\"Thulin\",\r\n		\"Tourcoing\",\r\n		\"Tournai\",\r\n		\"Valenciennes\",\r\n		\"Walcourt\",\r\n		\"Zottegem\",\r\n	 },\r\n	 france = {\r\n		\"Oostende\",\r\n		\"Breskens\",\r\n		\"Veurne\",\r\n	 },\r\n	 germany = {\r\n		\"Anhee\",\r\n		\"Boulay\",\r\n		\"Bouzonville\",\r\n		\"Carignan\",\r\n		\"Creutzwald-la-Croix\",\r\n		\"Damvillers\",\r\n		\"Dinant\",\r\n		\"Dun\",\r\n		\"Etain\",\r\n		\"Evrange\",\r\n		\"Faulquemont\",\r\n		\"Fontoy\",\r\n		\"Fresnes\",\r\n		\"Givet\",\r\n		\"Haybes\",\r\n		\"Jarny\",\r\n		\"Longuyon\",\r\n		\"Longwy\",\r\n		\"Metz\",\r\n		\"Metzervisse\",\r\n		\"Montmedy\",\r\n		\"Piennes\",\r\n		\"Raville\",\r\n		\"Revin\",\r\n		\"Sedan\",\r\n		\"Sierck-les-