Knokke\" },\r\n	 { \"gb18\", \"Montfaucon\" },\r\n	 { \"gb19\", \"Maubeuge\" },\r\n	 { \"gbiii12\", \"Antwerp\" },\r\n          { \"1dim\", \"Dinant\" },\r\n          { \"1ir\", \"Dinant\" },\r\n          { \"43ir\", \"Dinant\" },\r\n          { \"14c\", \"Dinant\" }\r\n	 { \"2dina\", \"Namur\" },\r\n	 { \"110ir\", \"Namur\" },\r\n	 { \"13dp\", \"Namur\" },\r\n	 { \"22dp\", \"Namur\" }\r\n          { \"4thmacrd\", \"Givet\" },\r\n          { \"104atr\", \"Givet\" },\r\n          { \"605rp\", \"Givet\" },\r\n          { \"101er\", \"Givet\" }\r\n	 { \"2ndlmd\", \"Sedan\" },\r\n	 { \"4blm\", \"Sedan\" },\r\n	 { \"8dc\", \"Sedan\" },\r\n	 { \"13rd\", \"Sedan\" }\r\n          { \"12dim\", \"Haybes\" },\r\n          { \"1bdm\", \"Haybes\" },\r\n          { \"13edble\", \"Haybes\" },\r\n          { \"106rim\", \"Haybes\" }\r\n	 { \"5dina\", \"Anhee\" },\r\n	 { \"14dp\", \"Anhee\" },\r\n	 { \"27ir\", \"Anhee\" },\r\n	 { \"6dp\", \"Anhee\" }\r\n          { \"1dia\", \"St.Omer\" }\r\n          { \"601gia\", \"Maubeuge\" }\r\n          { \"602gia\", \"Antwerp\" }\r\n	 { \"19df\", \"Antwerp\" },\r\n	 { \"37ds\", \"Bergen Op Zoom\" },\r\n	 { \"38ds\", \"Walsoorden\" },\r\n          { \"1id\", \"Hastiere\" },\r\n          { \"sas\", \"Hastiere\" },\r\n          { \"1gb\", \"Hastiere\" },\r\n          { \"3ib\", \"Hastiere\" },\r\n	 { \"2id\", \"Tienen\" },\r\n	 { \"2ab\", \"Tienen\" },\r\n	 { \"4ib\", \"Tienen\" },\r\n  	 { \"5ib\", \"Tienen\" }, \r\n          { \"3id\", \"Antwerp\" },\r\n	 { \"33ab\", \"Antwerp\" },\r\n	 { \"8ib\", \"Antwerp\" },\r\n  	 { \"9ib\", \"Antwerp\" },    \r\n          { \"60fw\", \"Knokke\" },\r\n          { \"60w\", \"Antwerp\" },\r\n          { \"61w\", \"Montfaucon\" },\r\n	 { \"70bw\", \"Knokke\" },\r\n	 { \"75w\", \"Montfaucon\" },\r\n	 { \"76w\", \"Brussels\" },\r\n	 { \"70w\", \"Antwerp\" },\r\n	 { \"52w\", \"St.Omer\" },\r\n          { \"1abd\", \"Brussels\" }\r\n          { \"1pb\", \"Montfaucon\" }\r\n          { \"2pb\", \"Maubeuge\" }\r\n	 }\r\n}\r\n---- Enable the \"INTEL\" system telling players where to fight?\r\n---- Recommended: false (for campaigns)\r\newsCheckEnabled = true\r\n\r\n---- Interval between EWS checks\r\n---- Recommended: timeInSeconds({ minutes = 15 })\r\newsCheckInterval = timeInSeconds({ minutes = 10 })\r\n\r\n-- Automatic attack objective controls\r\n\r\n-- true/false - should automatic attack objective placement be enabled\r\ngameAOPlacementEnabled = true\r\n-- How long should we wait after AOs become spare before notifying the HCs\r\ngameAONoticeDelay = timeInSeconds({ minutes = 2 })\r\n-- How long should we wait after notifying the HCs before placing an AO\r\ngameAOPlaceTime = timeInSeconds({ minutes = 2 })\r\n-- What fraction of available AOs must be placed?\r\ngameAOMinimumRatio = 0.75\r\n\r\n----------------------------------------------------------------------\r\n-- maxCaptureObjectives()\r\n--	Return the current maximum allowed capture objectives\r\n----------------------------------------------------------------------\r\n\r\nfunction maxCaptureObjectives (population)\r\n	-- If population is not specified, use the current chat population\r\n	if population == nil then population = getPopulation() end\r\n\r\n	local minimum, maximum = 3, 20\r\n	local populationPer = 55\r\n	local target = math.floor(population / populationPer)\r\n\r\n	if target > maximum then return maximum end\r\n	if target < minimum then return minimum end\r\n\r\n	-- Otherwise what we have is good\r\n	return target\r\nend\r\n\r\n\r\n\r\n\r\n', '2010-05-25 16:00:49'),
