CREATE DEFINER=`wwiiol`@`routine-runner` FUNCTION `f_rdp_adjustments`(
		i_id VARCHAR(8)
	,	i_vehtype_oid INT(11) UNSIGNED
	,	i_max_cycle INT(11) UNSIGNED
	) RETURNS text CHARSET latin1
    READS SQL DATA
BEGIN
	DECLARE l_adjustments TEXT ;
	SELECT	GROUP_CONCAT(r.cycle, ':', r.capacity)
	  INTO	l_adjustments
	  FROM	toe.rdp r
	 WHERE	r.id = i_id
			AND r.vehtype_oid = i_vehtype_oid
			AND r.cycle <= i_max_cycle
	 GROUP	BY r.id, r.vehtype_oid
	 ORDER	BY r.id, r.vehtype_oid, r.cycle
	;
	RETURN l_adjustments ;
END ;;
DELIMITER ;
