CREATE DEFINER=`wwiiol`@`routine-runner` PROCEDURE `p_get_unit_supply_audit`(
     i_unit_id INT(11) UNSIGNED
   , i_from INT(11) UNSIGNED
   , i_to INT(11) UNSIGNED
   , i_interval INT(11) UNSIGNED
   )
    READS SQL DATA
    SQL SECURITY INVOKER
BEGIN
	DECLARE l_fromDate DATETIME DEFAULT FROM_UNIXTIME(i_from) ;
	DECLARE l_toDate DATETIME DEFAULT FROM_UNIXTIME(i_to) ;
	SELECT	classid, fullname
	  FROM	wwiionline.wwii_vehclass ORDER BY 2 ;
	SELECT	vt.vehtype_oid, vt.classid
	  FROM	wwiionline.strat_hc_units u
			INNER JOIN toe.vehicles v ON (toe_template = id)
			INNER JOIN wwiionline.wwii_vehtype vt USING (vehtype_oid)
	 WHERE	u.unit_id = i_unit_id ORDER BY 1, 2;
    SELECT  wwii.f_date_round(sa.recorded, i_interval) AS `date`
		,	sa.vehtype_oid
        ,   AVG(sa.present * 100 / sa.capacity) AS `percent`
      FROM  audit.supply_full sa
     WHERE  unit_id = i_unit_id
       AND  sa.recorded >= l_fromDate
       AND  sa.recorded <= l_toDate
     GROUP  BY 1, 2
	;
END ;;
DELIMITER ;
