CREATE DEFINER=`wwiiol`@`routine-runner` FUNCTION `f_hcunit_seq`( i_unit_id SMALLINT(5) UNSIGNED ) RETURNS text CHARSET latin1
    READS SQL DATA
BEGIN
	DECLARE l_seq TEXT ;
	DECLARE l_unit_id SMALLINT(5) UNSIGNED DEFAULT i_unit_id ;
	DECLARE l_parent_id INT(11) UNSIGNED DEFAULT 0 ;
	DECLARE l_no_record TINYINT(1) UNSIGNED DEFAULT 0 ;

	DECLARE CONTINUE HANDLER FOR NOT FOUND SET l_no_record = 1 ;

	IF l_unit_id = 0 THEN RETURN "" ; END IF ;

	SET l_seq = l_unit_id ;

	REPEAT
		SELECT shu.parent_id INTO l_parent_id FROM wwiionline.strat_hc_units shu WHERE unit_id = l_unit_id ;
		IF l_no_record = 0 AND l_parent_id <> 0 THEN
			SET l_seq = CONCAT(l_parent_id, '-', l_seq) ;
		END IF ;
		SET l_unit_id = l_parent_id ;
	UNTIL l_no_record = 1 OR l_unit_id = 0 END REPEAT ;
	RETURN l_seq ;
END ;;
DELIMITER ;
