CREATE DEFINER=`wwiiol`@`routine-runner` PROCEDURE `p_persona_add_score`(
    forPlayer INT(11) unsigned
   , forPersona INT(11) unsigned
   , pointsScored INT(11) unsigned
   , onSortie INT(11) unsigned
   )
    MODIFIES SQL DATA
    SQL SECURITY INVOKER
BEGIN
 DECLARE i_persona_points INT(11) unsigned;
 DECLARE i_rank_id  INT unsigned;
 DECLARE i_next_rank_id  INT unsigned;
 DECLARE i_rank_points  INT(11) unsigned;
 DECLARE b_promoted  BOOL DEFAULT false;
 
 DECLARE b_success BOOL DEFAULT true;
 DECLARE CONTINUE HANDLER FOR NOT FOUND SET b_success = false;
 START TRANSACTION ;
 
 SELECT p.rankid, p.rankpoints, r.nextrank, r.pointsrequired
   INTO i_rank_id, i_persona_points, i_next_rank_id, i_rank_points
   FROM wwii_persona p
	INNER JOIN wwii_rank r USING (rankid)
  WHERE p.playerid = forPlayer
	AND p.personaid = forPersona
    FOR UPDATE
 ;
 IF b_success = true AND pointsScored > 0 THEN
   
   SET i_persona_points = i_persona_points + pointsScored;
   
   
   IF i_persona_points >= i_rank_points AND i_next_rank_id > 0 THEN
     SET b_promoted = true;
     SET i_rank_id = i_next_rank_id;
     SET i_persona_points = 0;
     UPDATE wwii_persona p
        SET rankid = i_next_rank_id, rankpoints = i_persona_points
      WHERE personaid = forPersona
     ;
   ELSE
     UPDATE wwii_persona p
	SET rankpoints = i_persona_points
      WHERE personaid = forPersona
	;
   END IF ;
 ELSE
   SET b_success = false ;
 END IF ;

 
 
 
 SELECT forPlayer, forPersona, b_success, b_promoted, i_rank_id, i_persona_points ; 
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;

