USE `audit`;

DELIMITER $$
--
-- Procedures
--
DROP PROCEDURE IF EXISTS `p_archive_events`$$
CREATE DEFINER=`wwiiol`@`localhost` PROCEDURE `p_archive_events` (`i_max_days` INT(11) UNSIGNED)  MODIFIES SQL DATA
    SQL SECURITY INVOKER
BEGIN
	DECLARE l_start_date DATETIME ;
	DECLARE l_end_date DATETIME ;
	DECLARE l_no_rows TINYINT(1) UNSIGNED DEFAULT 0 ;
	DECLARE l_rows_copied BIGINT(11) UNSIGNED DEFAULT 0 ;
	
	DECLARE	l_oldest_date DATETIME DEFAULT DATE_SUB(NOW(), INTERVAL 31 DAY) ;
	
	DECLARE l_max_days INT(11) UNSIGNED DEFAULT 7 ;
	
	DECLARE l_averaging_seconds INT(11) UNSIGNED DEFAULT 0 ;
	DECLARE CONTINUE HANDLER FOR NOT FOUND SET l_no_rows = 1 ;
	
	SELECT MIN(recorded) INTO l_start_date FROM `audit`.`events` ;
	IF l_no_rows = 1 THEN
		
		SELECT 0, "No value for recorded" ;
	ELSE
		
		SET l_end_date = DATE_ADD(l_start_date, INTERVAL i_max_days DAY) ;
		IF l_end_date > l_oldest_date THEN
			SET l_end_date = l_oldest_date ;
		END IF ;
		START TRANSACTION ;
		IF l_averaging_seconds > 0 THEN
			
			SET l_end_date = `wwii`.`f_date_rounded`(l_end_date, l_averaging_seconds) ;
				SELECT	`wwii`.`f_date_rounded`(`recorded`, l_averaging_seconds), `host`
						, `event`, AVG(`number`)
			  	FROM	`audit`.`events`
			 	WHERE	recorded < l_end_date
						AND EVENT NOT LIKE 'nc2-%'
						AND `number` <> 0
			 	GROUP	BY 1, 2
			 	ORDER	BY 1, 2
			;
		ELSE
			
				SELECT	recorded, host, event, number
			  	FROM	`audit`.`events`
			 	WHERE	recorded < l_end_date
						AND EVENT NOT LIKE 'nc2-%'
						AND `number` <> 0
				ORDER	BY 1, 2
			;
		END IF ;
		SET l_rows_copied = row_count() ;
		DELETE
		  FROM `audit`.`events`
		 WHERE recorded BETWEEN l_start_date AND l_end_date
		;
		SELECT 1, l_start_date, l_end_date, l_rows_copied, row_count() AS l_rows_deleted ;
	END IF ;
END$$

DROP PROCEDURE IF EXISTS `p_save_profile_results`$$
CREATE DEFINER=`wwiiol`@`localhost` PROCEDURE `p_save_profile_results` (`i_playerid` INT(11) UNSIGNED, `i_version_no` VARCHAR(15), `i_frames` INT(11) UNSIGNED, `i_min_time` FLOAT, `i_max_time` FLOAT, `i_total_time` FLOAT, `i_over_100` INT(11) UNSIGNED, `i_over_300` INT(11) UNSIGNED, `i_over_500` INT(11) UNSIGNED, `i_over_1000` INT(11) UNSIGNED, `i_peak_mem` INT(11) UNSIGNED, `i_os` VARCHAR(3), `i_num_cpus` INT(11) UNSIGNED, `i_cpu_flags` INT(11) UNSIGNED, `i_cpu_mhz` INT(11) UNSIGNED, `i_cpu_name` VARCHAR(64), `i_notes` TEXT)  MODIFIES SQL DATA
    SQL SECURITY INVOKER
BEGIN
		, total_frames, min_frame_time, max_frame_time, total_frame_time
		, frames_over_100ms, frames_over_300ms, frames_over_500ms, frames_over_1000ms
		, peak_mem
		, operating_system
		, num_cpus, cpu_flags, cpu_mhz, cpu_name
		, notes
		)
	VALUES
		( NOW(), i_playerid, INET_ATON(i_version_no)
		, i_frames, i_min_time, i_max_time, i_total_time
		, i_over_100, i_over_300, i_over_500, i_over_1000
		, i_peak_mem
		, i_os
		, i_num_cpus, i_cpu_flags, i_cpu_mhz, i_cpu_name
		, i_notes
		) ;
END$$

DROP PROCEDURE IF EXISTS `p_score_analysis`$$
CREATE DEFINER=`wwiiol`@`localhost` PROCEDURE `p_score_analysis` ()  MODIFIES SQL DATA
    SQL SECURITY INVOKER
BEGIN
	DECLARE l_last_persona_id, l_last_rank, l_personaid, l_branchid, l_old_rank, l_new_rank INT(11) UNSIGNED ;
	DECLARE l_last_recorded, l_recorded DATETIME ;
	DECLARE l_done TINYINT(1) UNSIGNED DEFAULT 0 ;
	DECLARE curs CURSOR FOR
		SELECT	r.personaid, r.recorded, p.branchid, r.old_rank, r.new_rank
		  FROM	`audit`.`rank` r
				INNER JOIN `wwiionline`.`wwii_persona` p USING (personaid)
		 ORDER	BY 1, 2
	;
	DECLARE CONTINUE HANDLER FOR NOT FOUND SET l_done = 1 ;
	OPEN curs ;
	REPEAT
		FETCH curs INTO l_personaid, l_recorded, l_branchid, l_old_rank, l_new_rank ;
		IF NOT l_done THEN
			IF l_personaid = l_last_persona_id AND l_old_rank = l_last_rank AND l_new_rank = l_last_rank + 1 THEN
					, FLOOR((UNIX_TIMESTAMP(l_recorded) - UNIX_TIMESTAMP(l_last_recorded)) / 3600 + 0.5)
					, 1
					)
				;
			END IF ;
			SET l_last_persona_id = l_personaid, l_last_rank = l_new_rank, l_last_recorded = l_recorded ;
		END IF ;
	UNTIL l_done END REPEAT ;
	CLOSE curs ;
END$$

