CREATE DEFINER=`wwiiol`@`localhost` FUNCTION `f_supply_start_date` () RETURNS DATETIME READS SQL DATA
    SQL SECURITY INVOKER
BEGIN
	DECLARE l_no_record TINYINT(1) UNSIGNED DEFAULT 0 ;
	DECLARE l_date DATETIME DEFAULT NOW() ;
	DECLARE CONTINUE HANDLER FOR NOT FOUND SET l_no_record = 1 ;
	SELECT MIN(recorded) INTO l_date FROM audit.supply ;
	RETURN l_date ;
END$$

