--
-- Database: `auth`
--
DROP DATABASE IF EXISTS `auth`;
CREATE DATABASE IF NOT EXISTS `auth` DEFAULT CHARACTER SET latin1 COLLATE latin1_swedish_ci;
USE `auth`;

DELIMITER $$
--
-- Procedures
--
DROP PROCEDURE IF EXISTS `p_authenticate_steam_user_for_arena`$$
CREATE DEFINER=`wwiiol`@`localhost` PROCEDURE `p_authenticate_steam_user_for_arena` (`i_steamid` INT(11) UNSIGNED, `i_arena_id` INT(11) UNSIGNED)  READS SQL DATA
    SQL SECURITY INVOKER
BEGIN
  DECLARE l_not_found TINYINT(1) UNSIGNED DEFAULT 0;
  DECLARE CONTINUE HANDLER FOR NOT FOUND SET l_not_found = 1;

  SELECT  IF ( s.status = 'active', 1, 0 ) AS is_active
     ,  p.playerID, c.handle
     ,  IF ( c.flags & 2, 1, 0 ) AS have_hw_info
    FROM wwiiol_players p
      INNER JOIN auth_customer c USING (customerID)
      INNER JOIN auth_subscribed s USING (customerID)
      INNER JOIN auth_subarenaassoc a USING (subscriptionID)
      INNER JOIN auth_steamcustomer m USING (customerID)
       WHERE m.steamID = i_steamid
         AND a.arenaID = i_arena_id
       ORDER BY s.status ASC
       LIMIT 1
  ;
END$$

DROP PROCEDURE IF EXISTS `p_authenticate_user_for_arena`$$
CREATE DEFINER=`wwiiol`@`localhost` PROCEDURE `p_authenticate_user_for_arena` (`i_callsign` VARCHAR(16), `i_password` TEXT, `i_arena_id` INT(11) UNSIGNED)  READS SQL DATA
    SQL SECURITY INVOKER
BEGIN

	DECLARE l_not_found TINYINT(1) UNSIGNED DEFAULT 0 ;

	
	DECLARE CONTINUE HANDLER FOR NOT FOUND SET l_not_found = 1 ;

	
	SELECT	IF ( c.password = i_password, 1, 0 ) AS password_match
		 ,	IF ( s.status = 'active', 1, 0 ) AS is_active
		 ,	p.playerID, c.handle
		 ,	IF ( c.flags & 2, 1, 0 ) AS have_hw_info
	  FROM wwiiol_players p
			INNER JOIN auth_customer c USING (customerID)
			INNER JOIN auth_subscribed s USING (customerID)
			INNER JOIN auth_subarenaassoc a USING (subscriptionID)
			 WHERE c.username = i_callsign
				 AND a.arenaID = i_arena_id
			 ORDER BY s.status ASC
			 LIMIT 1
	;

END$$

DROP PROCEDURE IF EXISTS `p_get_chat_group_summary`$$
CREATE DEFINER=`wwiiol`@`localhost` PROCEDURE `p_get_chat_group_summary` ()  READS SQL DATA
    SQL SECURITY INVOKER
BEGIN
	SELECT	cg.group_oid
	     ,	IF(cg.enabled='Y', 1, 0) AS enabled
	     ,	MAX(IF(cgr.branchid = 1, cgr.max_rank, NULL)) AS max_army_rank
	     ,	MAX(IF(cgr.branchid = 2, cgr.max_rank, NULL)) AS max_air_rank
	     ,	MAX(IF(cgr.branchid = 3, cgr.max_rank, NULL)) AS max_navy_rank
	     ,	cg.max_squad_rank
	     ,	cg.grants
	     ,  GROUP_CONCAT(cgv.vehtype_oid) AS vehtype_oids
	  FROM	`auth`.`chat_groups` cg
			LEFT OUTER JOIN `wwiionline`.`chat_group_ranks` cgr USING (group_oid)
			LEFT OUTER JOIN `wwiionline`.`chat_group_vehs_cache` cgv ON (cg.group_oid = cgv.group_oid)
	 GROUP	BY 1
	;
END$$

DROP PROCEDURE IF EXISTS `p_get_player_details`$$
CREATE DEFINER=`wwiiol`@`localhost` PROCEDURE `p_get_player_details` (`i_player_id` INT(11) UNSIGNED, `i_arena_id` INT(11) UNSIGNED)  READS SQL DATA
    SQL SECURITY INVOKER
BEGIN
	SELECT	pl.playerid AS `playerid`
	     ,	auth.f_player_permissions(pl.playerid) AS `permissions`
	     ,	pl.callsign AS `callsign`
	     ,	pl.customerid AS `customerid`
	     ,	pl.squadid AS `squadid`
	     ,	pl.squad_rank AS `squad_rank`
	     ,	s.short_name AS `squad_short_name`
	     ,	pl.player_decal AS `player_decal`
	     ,	pl.locktime AS `lock_unixtime`
	     ,	pl.lockside AS `lock_side`
	     ,	pl.last_poll AS `last_poll`
	     ,	pl.last_login AS `last_login`
	     ,	GROUP_CONCAT(DISTINCT(v.group_oid)) AS `groups`
	     ,	FROM_UNIXTIME(pl.locktime) AS `lock_datetime`
		 ,	NULL AS `minutes`
	  FROM	`wwiionline`.`wwii_player` pl
			LEFT OUTER JOIN `auth`.`v_customer_active_groups` v
				ON (pl.customerid = v.customerid AND v.arenaid = i_arena_id)
			LEFT OUTER JOIN `wwiionline`.`wwii_squads` s
				ON (pl.squadid = s.squadid)
	 WHERE	pl.playerid = i_player_id
	 GROUP	BY pl.playerid
	;
END$$

DROP PROCEDURE IF EXISTS `p_get_steam_user_subscriptions`$$
CREATE DEFINER=`wwiiol`@`localhost` PROCEDURE `p_get_steam_user_subscriptions` (`i_steamid` INT(11) UNSIGNED)  READS SQL DATA
    SQL SECURITY INVOKER
BEGIN
  DECLARE l_not_found TINYINT(1) UNSIGNED DEFAULT 0;
  DECLARE CONTINUE HANDLER FOR NOT FOUND SET l_not_found = 1;

  SELECT  IF ( s.status = 'active', 1, 0 ) AS is_active
     ,  p.playerID
     ,  1 AS have_hw_info
     ,  IF ( ps.status = 'active', 1, 0 ) AS is_playnet
     ,  (
        SELECT  GROUP_CONCAT(DISTINCT(a.arenaID))
          FROM  auth_subscribed s
            INNER JOIN auth_subarenaassoc a USING (subscriptionID)
            INNER JOIN auth_arenas aa USING (arenaID)
         WHERE  s.customerID = c.customerID
            AND s.status = 'active'
         GROUP BY s.customerID
         ORDER BY a.arenaID
      ) AS subs
    , IF ( s.status = 'active', 'Y', 'N' ) AS is_premium
    FROM wwiiol_players p
      INNER JOIN auth_customer c USING (customerID)
      INNER JOIN auth_subscribed s USING (customerID)
      INNER JOIN auth_steamcustomer m USING (customerID)
      LEFT OUTER JOIN auth_subscribed ps
        ON (ps.customerid = p.customerid AND ps.subscriptionid = 9)
       WHERE m.steamID = i_steamid
       ORDER BY s.status ASC
       LIMIT 1
  ;
END$$

DROP PROCEDURE IF EXISTS `p_get_user_subscriptions`$$
CREATE DEFINER=`wwiiol`@`localhost` PROCEDURE `p_get_user_subscriptions` (`i_callsign` VARCHAR(16), `i_password` TEXT)  READS SQL DATA
    SQL SECURITY INVOKER
BEGIN

	DECLARE l_not_found TINYINT(1) UNSIGNED DEFAULT 0 ;

	
	DECLARE CONTINUE HANDLER FOR NOT FOUND SET l_not_found = 1 ;

	
	SELECT	IF ( c.password = i_password, 1, 0 ) AS password_match
		 ,	IF ( s.status = 'active', 1, 0 ) AS is_active
		 ,	p.playerID
		 ,	1 AS have_hw_info 
		 ,	IF ( ps.status = 'active', 1, 0 ) AS is_playnet
		 ,	(
				SELECT	GROUP_CONCAT(DISTINCT(a.arenaID))
				  FROM	auth_subscribed s
						INNER JOIN auth_subarenaassoc a USING (subscriptionID)
						INNER JOIN auth_arenas aa USING (arenaID)
				 WHERE	s.customerID = c.customerID
						AND s.status = 'active'
				 GROUP	BY s.customerID
				 ORDER	BY a.arenaID
			) AS subs
		,	IF ( s.status = 'active', 'Y', 'N' ) AS is_premium	
	  FROM wwiiol_players p
			INNER JOIN auth_customer c USING (customerID)
			INNER JOIN auth_subscribed s USING (customerID)
			LEFT OUTER JOIN auth_subscribed ps
				ON (ps.customerid = p.customerid AND ps.subscriptionid = 9)
			 WHERE c.username = i_callsign
			 ORDER BY s.status ASC
			 LIMIT 1
	;

END$$

DROP PROCEDURE IF EXISTS `p_persona_refresh`$$
CREATE DEFINER=`wwiiol`@`localhost` PROCEDURE `p_persona_refresh` (`i_persona_id` INT(11) UNSIGNED, `i_arena_id` INT(11) UNSIGNED)  READS SQL DATA
    SQL SECURITY INVOKER
BEGIN
	SELECT	pe.rankid AS `rank_id`
	     ,	pe.rankpoints AS `rank_points`
	     ,	auth.f_player_permissions(pe.playerid) AS `permissions`
	     ,	GROUP_CONCAT(DISTINCT(v.group_oid)) AS `groups`
	     ,	amb.balance AS `minute_balance`
	  FROM	wwiionline.wwii_persona pe
			INNER JOIN wwiionline.wwii_player pl USING (playerid)	 
			LEFT OUTER JOIN `auth`.`auth_minute_balance` amb
				USING (customerid)
			LEFT OUTER JOIN auth.v_customer_active_groups v
				ON (pl.customerid = v.customerid AND v.arenaid = i_arena_id)
	 WHERE	pe.personaid = i_persona_id
	 GROUP	BY pe.personaid
	;
END$$

--
-- Functions
--
DROP FUNCTION IF EXISTS `f_player_permissions`$$
CREATE DEFINER=`wwiiol`@`localhost` FUNCTION `f_player_permissions` (`i_player_id` INT(11) UNSIGNED) RETURNS BIGINT(20) UNSIGNED READS SQL DATA
    SQL SECURITY INVOKER
BEGIN
	DECLARE l_permissions BIGINT(20) UNSIGNED DEFAULT 0 ;
	SELECT	BIT_OR(pe.maskvalue) INTO l_permissions
	  FROM	wwiionline.wwii_player_permiss wpp
			INNER JOIN auth.wwii_permissions pe
				USING (`permissionid`)
	 WHERE	wpp.playerid = i_player_id
	;
	RETURN l_permissions ;
END$$

DELIMITER ;

