--
-- Database: `toe`
--
DROP DATABASE IF EXISTS `toe`;
CREATE DATABASE IF NOT EXISTS `toe` DEFAULT CHARACTER SET latin1 COLLATE latin1_swedish_ci;
USE `toe`;

DELIMITER $$
--
-- Procedures
--
DROP PROCEDURE IF EXISTS `p_get_unit_supply_audit`$$
CREATE DEFINER=`wwiiol`@`localhost` PROCEDURE `p_get_unit_supply_audit` (`i_unit_id` INT(11) UNSIGNED, `i_from` INT(11) UNSIGNED, `i_to` INT(11) UNSIGNED, `i_interval` INT(11) UNSIGNED)  READS SQL DATA
    SQL SECURITY INVOKER
BEGIN
	DECLARE l_fromDate DATETIME DEFAULT FROM_UNIXTIME(i_from) ;
	DECLARE l_toDate DATETIME DEFAULT FROM_UNIXTIME(i_to) ;
	SELECT	classid, fullname
	  FROM	wwiionline.wwii_vehclass ORDER BY 2 ;
	SELECT	vt.vehtype_oid, vt.classid
	  FROM	wwiionline.strat_hc_units u
			INNER JOIN toe.vehicles v ON (toe_template = id)
			INNER JOIN wwiionline.wwii_vehtype vt USING (vehtype_oid)
	 WHERE	u.unit_id = i_unit_id ORDER BY 1, 2;
    SELECT  wwii.f_date_round(sa.recorded, i_interval) AS `date`
		,	sa.vehtype_oid
        ,   AVG(sa.present * 100 / sa.capacity) AS `percent`
      FROM  audit.supply_full sa
     WHERE  unit_id = i_unit_id
       AND  sa.recorded >= l_fromDate
       AND  sa.recorded <= l_toDate
     GROUP BY 1, 2
	;
END$$

DROP PROCEDURE IF EXISTS `p_rdp_cycle_action`$$
CREATE DEFINER=`wwiiol`@`localhost` PROCEDURE `p_rdp_cycle_action` (`i_current` INT(11) UNSIGNED, `i_next` INT(11) UNSIGNED)  BEGIN
    DECLARE l_notation CHAR(1) DEFAULT 'x' ;
    DECLARE l_description VARCHAR(10) DEFAULT "Unknown" ;
    DECLARE l_units INT(11) UNSIGNED DEFAULT 0 ;
    CASE
        WHEN i_current = i_next
            THEN    SELECT '=', "=", 0 INTO l_notation, l_description, l_units ;
        WHEN i_current <= 0 AND i_next > 0
            THEN    SELECT '+', "Intro", i_next INTO l_notation, l_description, l_units ;
        WHEN i_current > 0 AND i_next > i_current
            THEN    SELECT '>', "Increase", i_next - i_current INTO l_notation, l_description, l_units ;
        WHEN i_next > 1
            THEN    SELECT '<', "Decrease", i_current - i_next INTO l_notation, l_description, l_units ;
        WHEN i_next = 1
            THEN    SELECT '-', "PhaseOut", i_current - i_next INTO l_notation, l_description, l_units ;
        WHEN i_next = 0
            THEN    SELECT 'x', "Withdrawl", i_current - i_next INTO l_notation, l_description, l_units ;
        ELSE
            SELECT '*', 'Unknown', 0 INTO l_notation, l_description, l_units ;
    END CASE ;
    SELECT l_notation as notation, l_description as description, l_units as units ;
END$$

DROP PROCEDURE IF EXISTS `p_restart_cycles`$$
CREATE DEFINER=`wwiiol`@`localhost` PROCEDURE `p_restart_cycles` ()  MODIFIES SQL DATA
BEGIN  UPDATE `toe`.`headers` SET current_cycle = 0 ;  UPDATE `toe`.`vehicles` SET capacity = cycle0 ;  SELECT "TOEs returned to Cycle0" as `result` FROM DUAL ; END$$

DROP PROCEDURE IF EXISTS `p_supply_audit_archive`$$
CREATE DEFINER=`wwiiol`@`localhost` PROCEDURE `p_supply_audit_archive` ()  MODIFIES SQL DATA
    SQL SECURITY INVOKER
BEGIN
	DECLARE l_done TINYINT(1) UNSIGNED DEFAULT 0 ;
	DECLARE L_INTERVAL INT(11) UNSIGNED DEFAULT 1800 ;
	DECLARE	l_max_date DATETIME DEFAULT FROM_UNIXTIME(wwii.f_date_round(DATE_SUB(NOW(), INTERVAL 14 DAY), L_INTERVAL)) ;
	DECLARE l_start_date DATETIME ;
	DECLARE l_end_date DATETIME ;
	DECLARE l_last_unit_id, l_last_vehtype_oid, l_last_unix, l_last_present, l_last_capacity INT(11) UNSIGNED DEFAULT 0 ;
	DECLARE l_unit_id, l_vehtype_oid, l_unix, l_present, l_capacity INT(11) UNSIGNED DEFAULT 0 ;
	DECLARE l_last_recorded, l_recorded DATETIME ;
	DECLARE l_rows_read, l_rows_written INT(11) UNSIGNED DEFAULT 0 ;
	DECLARE	curs CURSOR FOR
		SELECT	unit_id, vehtype_oid, recorded, present, capacity, wwii.f_date_round(recorded, L_INTERVAL)
		  FROM	audit.supply
		 WHERE	recorded < l_end_date
		 ORDER	BY 1, 2, 3
	;
	DECLARE CONTINUE HANDLER FOR NOT FOUND SET l_done = 1 ;
	SELECT MIN(recorded) INTO l_start_date FROM audit.supply ;
	IF l_done = 0 THEN
		SET l_end_date = DATE_ADD(l_start_date, INTERVAL 90 MINUTE) ;
		IF l_end_date > l_max_date THEN
			SET l_end_date = l_max_date ;
		END IF ;
	ELSE
		SET l_done = 0, l_end_date = l_max_date ;
	END IF ;
	SET l_end_date = wwii.f_date_rounded(l_end_date, L_INTERVAL) ;
	START TRANSACTION ;
	OPEN curs ;
	REPEAT
		FETCH curs INTO l_unit_id, l_vehtype_oid, l_recorded, l_present, l_capacity, l_unix ;
		IF NOT l_done THEN
			IF l_last_unit_id = 0 OR
				l_last_unix <> l_unix OR
				 l_last_vehtype_oid <> l_vehtype_oid OR
				 l_last_unit_id <> l_unit_id
			 THEN
				VALUES	(l_last_unit_id, l_last_vehtype_oid, l_last_recorded, l_last_present, l_last_capacity)
				;
				SET l_rows_written = l_rows_written + 1 ;
			END IF ;
			SET l_last_unix = l_unix, l_last_vehtype_oid = l_vehtype_oid, l_last_unit_id = l_unit_id, l_last_recorded = l_recorded
			  ,	l_last_present = l_present, l_last_capacity = l_capacity, l_rows_read = l_rows_read + 1 ;
		END IF ;
	UNTIL l_done END REPEAT ;
	
	IF l_last_unit_id > 0 THEN
		VALUES	(l_last_unit_id, l_last_vehtype_oid, l_last_recorded, l_last_present, l_last_capacity)
		;
		SET l_rows_written = l_rows_written + 1 ;
	END IF ;
	CLOSE curs ;
	COMMIT ;
	SELECT l_rows_read, l_rows_written, ROW_COUNT(), l_start_date, l_end_date, l_max_date ;
END$$

--
-- Functions
--
DROP FUNCTION IF EXISTS `f_rdp_adjustments`$$
CREATE DEFINER=`wwiiol`@`localhost` FUNCTION `f_rdp_adjustments` (`i_id` VARCHAR(8), `i_vehtype_oid` INT(11) UNSIGNED, `i_max_cycle` INT(11) UNSIGNED) RETURNS TEXT CHARSET latin1 READS SQL DATA
BEGIN
	DECLARE l_adjustments TEXT ;
	SELECT	GROUP_CONCAT(r.cycle, ':', r.capacity)
	  INTO	l_adjustments
	  FROM	toe.rdp r
	 WHERE	r.id = i_id
			AND r.vehtype_oid = i_vehtype_oid
			AND r.cycle <= i_max_cycle
	 GROUP	BY r.id, r.vehtype_oid
	 ORDER	BY r.id, r.vehtype_oid, r.cycle
	;
	RETURN l_adjustments ;
END$$

DROP FUNCTION IF EXISTS `f_rdp_cycle_action`$$
CREATE DEFINER=`wwiiol`@`localhost` FUNCTION `f_rdp_cycle_action` (`i_current` INT(11) UNSIGNED, `i_next` INT(11) UNSIGNED) RETURNS CHAR(1) CHARSET latin1 SQL SECURITY INVOKER
BEGIN
	
	DECLARE l_type CHAR(1) DEFAULT '?' ;
	CASE
		WHEN i_current = i_next THEN					SET l_type = '=' ;
		WHEN i_current <= 0 AND i_next > 0 THEN			SET l_type = '+' ;
		WHEN i_current > 0 AND i_next > i_current THEN	SET l_type = '>' ;
		WHEN i_next > 1 THEN							SET l_type = '<' ;
		WHEN i_next = 1 THEN							SET l_type = '-' ;
		WHEN i_next = 0 THEN							SET l_type = 'x' ;
	END CASE ;
	RETURN l_type ;
END$$

DELIMITER ;

