DROP TABLE IF EXISTS `v_in_progress`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`127.0.0.1` SQL SECURITY DEFINER VIEW `v_in_progress`  AS  select `c`.`countryID` AS `country_id`,`c`.`current_cycle` AS `cycle_in_progress`,`c`.`rdp_percent` AS `percent_done`,`v`.`id` AS `toe_template`,`vt`.`fullName` AS `veh_name`,`vt`.`categoryID` AS `veh_category_id`,`vt`.`classID` AS `veh_class_id`,`vt`.`typeID` AS `veh_type_id`,`f_rdp_cycle_action`(`v`.`capacity`,`rdp`.`capacity`) AS `action`,`v`.`capacity` AS `current_capacity`,`rdp`.`capacity` AS `next_capacity` from (((`vehicles` `v` join `rdp` on(((`v`.`id` = `rdp`.`id`) and (`v`.`vehtype_oid` = `rdp`.`vehtype_oid`)))) join `wwiionline`.`wwii_vehtype` `vt` on((`v`.`vehtype_oid` = `vt`.`vehtype_oid`))) join `wwiionline`.`wwii_country` `c` on((`vt`.`countryID` = `c`.`countryID`))) where (`rdp`.`cycle` = `c`.`current_cycle`) ;

