USE `wwii`;

DELIMITER $$
--
-- Procedures
--
DROP PROCEDURE IF EXISTS `p_add_kill`$$
CREATE DEFINER=`wwiiol`@`localhost` PROCEDURE `p_add_kill` (`i_killer_id` INT(11) UNSIGNED, `i_killer_player_0` INT(11) UNSIGNED, `i_killer_persona_0` INT(11) UNSIGNED, `i_killer_player_1` INT(11) UNSIGNED, `i_killer_persona_1` INT(11) UNSIGNED, `i_killer_country` TINYINT(3) UNSIGNED, `i_killer_category` TINYINT(3) UNSIGNED, `i_killer_class` TINYINT(3) UNSIGNED, `i_killer_type` TINYINT(3) UNSIGNED, `i_victim_id` INT(11) UNSIGNED, `i_victim_player_0` INT(11) UNSIGNED, `i_victim_persona_0` INT(11) UNSIGNED, `i_victim_player_1` INT(11) UNSIGNED, `i_victim_persona_1` INT(11) UNSIGNED, `i_victim_country` TINYINT(3) UNSIGNED, `i_victim_category` TINYINT(3) UNSIGNED, `i_victim_class` TINYINT(3) UNSIGNED, `i_victim_type` TINYINT(3) UNSIGNED, `i_kill_value` INT(11) UNSIGNED, `i_dead_x` INT(11), `i_dead_y` INT(11), `i_dead_z` INT(11))  MODIFIES SQL DATA
    SQL SECURITY INVOKER
BEGIN
	DECLARE l_insert_error TINYINT(1) UNSIGNED DEFAULT 0 ;
	DECLARE CONTINUE HANDLER FOR SQLSTATE '23000' SET l_insert_error = 1 ;
	START TRANSACTION ;

	
			kill_time
		,	victim_sortie_id
		,	victim_player_0
		,	victim_player_1
		,	killer_sortie_id
		,	killer_player_0
		,	killer_player_1
		,	dead_x, dead_y, dead_z
		,	victim_country, victim_category, victim_class, victim_type
		,	victim_vehtype_oid
		,	killer_country, killer_category, killer_class, killer_type
		,	killer_vehtype_oid
		)
	VALUES
		(
			NOW()
		,	i_victim_id
		,	i_victim_player_0
		,	i_victim_player_1
		,	i_killer_id
		,	(SELECT kps0.player_id FROM wwiionline.wwii_sortie kps0 WHERE kps0.sortie_id = i_killer_id AND kps0.is_pilot = 1)
		,	(SELECT kps1.player_id FROM wwiionline.wwii_sortie kps1 WHERE kps1.sortie_id = i_killer_id AND kps1.is_pilot = 0)
		,	i_dead_x, i_dead_y, i_dead_z
		,	i_victim_country, i_victim_category, i_victim_class, i_victim_type
		,	(SELECT vehtype_oid FROM wwiionline.wwii_vehtype WHERE countryID = i_victim_country AND categoryID = i_victim_category AND classID = i_victim_class AND typeID = i_victim_type)
		,	i_killer_country, i_killer_category, i_killer_class, i_killer_type
		,	(SELECT vehtype_oid FROM wwiionline.wwii_vehtype WHERE countryID = i_killer_country AND categoryID = i_killer_category AND classID = i_killer_class AND typeID = i_killer_type)
		)
	;
	IF l_insert_error = 0 THEN
		COMMIT ;
	ELSE
		ROLLBACK ;
	END IF ;
END$$

DROP PROCEDURE IF EXISTS `p_add_player_note`$$
CREATE DEFINER=`wwiiol`@`localhost` PROCEDURE `p_add_player_note` (`i_callsign` VARCHAR(10) CHARSET ucs2, `i_issuedBy` INT(11) UNSIGNED, `i_note_type_id` INT(11) UNSIGNED, `i_note` TEXT)  MODIFIES SQL DATA
    SQL SECURITY INVOKER
BEGIN
	DECLARE l_playerID INT(11) unsigned DEFAULT 0 ;
	DECLARE	l_isPlaynet TINYINT(1) unsigned DEFAULT 0 ;

	DECLARE l_last_row_fetched INT(11) UNSIGNED DEFAULT 0 ;

	DECLARE CONTINUE HANDLER FOR NOT FOUND SET l_last_row_fetched = 1 ;

	SELECT	p.playerid, p.isPlaynet
	  INTO	l_playerID, l_isPlaynet
	  FROM	`wwiionline`.`wwii_player` p
	 WHERE	p.callsign = LOWER(i_callsign)
	;

	IF l_last_row_fetched THEN

		SELECT 0 AS err, "No such player" AS txt ;

	ELSE

		VALUES	(l_playerID, i_note_type_id, NOW(), NULL, i_issuedBy, i_note)
		;

		COMMIT ;

		SELECT l_playerID AS player ;

	END IF ;

END$$

DROP PROCEDURE IF EXISTS `p_add_sortie`$$
CREATE DEFINER=`wwiiol`@`localhost` PROCEDURE `p_add_sortie` (`i_sortie_id` INT(11) UNSIGNED, `i_crew_0_id` INT(11) UNSIGNED, `i_crew_0_persona_id` INT(11) UNSIGNED, `i_crew_1_id` INT(11) UNSIGNED, `i_crew_1_persona_id` INT(11) UNSIGNED, `i_brigade_id` SMALLINT UNSIGNED, `i_facility_oid` INT(11) UNSIGNED, `i_weap_country` TINYINT(3) UNSIGNED, `i_weap_category` TINYINT(3) UNSIGNED, `i_weap_class` TINYINT(3) UNSIGNED, `i_weap_type` TINYINT(3) UNSIGNED, `i_mission_type` SMALLINT UNSIGNED, `i_mission_id` INT(11) UNSIGNED, `i_cell_host_ip` TINYINT(3) UNSIGNED)  MODIFIES SQL DATA
    SQL SECURITY INVOKER
BEGIN
	IF i_crew_1_id IS NULL or i_crew_1_id = 0 THEN
		INSERT HIGH_PRIORITY INTO `wwiionline`.`wwii_sortie`
			(
			  sortie_id
			, player_id, personaid, is_pilot
			, brigade_id, facility_oid
			, vcountry, vcategory, vclass, vtype
			, mission_type, mission_id
			, cell_host_ip
			, added
			)
		VALUES
			(
			  i_sortie_id
			, i_crew_0_id, i_crew_0_persona_id, 1
			, i_brigade_id, i_facility_oid
			, i_weap_country, i_weap_category, i_weap_class, i_weap_type
			, i_mission_type, i_mission_id
			, i_cell_host_ip
			, NOW()
			) ;
	ELSE
		INSERT HIGH_PRIORITY INTO `wwiionline`.`wwii_sortie`
			(
			  sortie_id
			, player_id, personaid, is_pilot
			, brigade_id, facility_oid
			, vcountry, vcategory, vclass, vtype
			, mission_type, mission_id
			, cell_host_ip
			, added
			)
		VALUES
			(
			  i_sortie_id
			, i_crew_0_id, i_crew_0_persona_id, 1
			, i_brigade_id, i_facility_oid
			, i_weap_country, i_weap_category, i_weap_class, i_weap_type
			, i_mission_type, i_mission_id
			, i_cell_host_ip
			, NOW()
			)
		,	(
			  i_sortie_id
			, i_crew_1_id, i_crew_1_persona_id, 0
			, i_brigade_id, i_facility_oid
			, i_weap_country, i_weap_category, i_weap_class, i_weap_type
			, i_mission_type, i_mission_id
			, i_cell_host_ip
			, NOW()
			) ;
	END IF ;
END$$

DROP PROCEDURE IF EXISTS `p_archive_connections`$$
CREATE DEFINER=`wwiiol`@`localhost` PROCEDURE `p_archive_connections` (`i_num_days` INT(11) UNSIGNED)  MODIFIES SQL DATA
    SQL SECURITY INVOKER
BEGIN
	DECLARE l_start_date DATETIME ;
	DECLARE l_end_date DATETIME ;
	DECLARE	l_max_date DATETIME DEFAULT DATE_SUB(NOW(), INTERVAL 60 DAY) ;
	DECLARE l_no_rows TINYINT(1) UNSIGNED DEFAULT 0 ;
	DECLARE CONTINUE HANDLER FOR NOT FOUND SET l_no_rows = 1 ;
	SELECT MIN(recorded) INTO l_start_date FROM audit.connections ;
	IF l_no_rows = 1 THEN
		SELECT 0, "No value for recorded" ;
	ELSE
		SET l_end_date = DATE_ADD(l_start_date, INTERVAL i_num_days DAY) ;
		IF l_end_date > l_max_date THEN
			SET l_end_date = l_max_date ;
		END IF ;
		START TRANSACTION ;
			SELECT * FROM audit.connections
			 WHERE recorded BETWEEN l_start_date AND l_end_date
		;
		DELETE
		  FROM audit.connections
		 WHERE recorded BETWEEN l_start_date AND l_end_date
		;
		SELECT 1, l_start_date, l_end_date, row_count() ;
	END IF ;
END$$

DROP PROCEDURE IF EXISTS `p_ban_player`$$
CREATE DEFINER=`wwiiol`@`localhost` PROCEDURE `p_ban_player` (`i_callsign` VARCHAR(10) CHARSET ucs2, `i_banFor` INT(11) UNSIGNED, `i_issuedBy` INT(11) UNSIGNED, `i_reason` TEXT)  MODIFIES SQL DATA
    SQL SECURITY INVOKER
BEGIN
	DECLARE l_playerID INT(11) unsigned DEFAULT 0 ;
	DECLARE	l_isPlaynet TINYINT(1) unsigned DEFAULT 0 ;

	DECLARE l_note_type_id INT(11) UNSIGNED DEFAULT 0 ;
	DECLARE l_bans INT(11) UNSIGNED DEFAULT 0 ;
	DECLARE l_last_row_fetched INT(11) UNSIGNED DEFAULT 0 ;

	DECLARE CONTINUE HANDLER FOR NOT FOUND SET l_last_row_fetched = 1 ;

	START TRANSACTION ;

	SELECT	p.playerid, p.isPlaynet, (SELECT COUNT(*) FROM `wwiionline`.`player_notes` n WHERE n.playerid = p.playerid AND n.note_type_id = 2)
	  INTO	l_playerID, l_isPlaynet, l_bans
	  FROM	`wwiionline`.`wwii_player` p
	 WHERE	p.callsign = LOWER(i_callsign)
	   FOR	UPDATE
	;

	IF l_last_row_fetched THEN

		ROLLBACK ;
		SELECT 0, "No such player" ;

	ELSEIF l_isPlaynet > 0 THEN

		ROLLBACK ;
		SELECT 0, "Cannot issue bans on CRS accounts" ;

	ELSE

		IF i_banFor > 0 THEN 
			UPDATE	`wwiionline`.`wwii_player`
	   		SET	lockside = 3
		 		,	locktime = UNIX_TIMESTAMP() + i_banFor
	 		WHERE	playerID = l_playerID
			;

			SET l_bans = l_bans + 1 ;

			VALUES	(l_playerID, 2, NOW(), FROM_UNIXTIME(UNIX_TIMESTAMP() + i_banFor), i_issuedBy, i_reason)
			;

			COMMIT ;
		ELSE
			ROLLBACK ;
		END IF ;

		SELECT l_playerID, l_bans ;

	END IF ;

END$$

DROP PROCEDURE IF EXISTS `p_feb_11_promo_list`$$
CREATE DEFINER=`wwiiol`@`localhost` PROCEDURE `p_feb_11_promo_list` ()  READS SQL DATA
    SQL SECURITY INVOKER
BEGIN
	
	DECLARE l_min_sorties INT(11) UNSIGNED DEFAULT 20 ;
	
	DECLARE l_min_seconds INT(11) UNSIGNED DEFAULT 2 * 60 * 60;
	SELECT	DISTINCT pl.customerid, COUNT(*) AS sorties, SUM(UNIX_TIMESTAMP(return_time) - UNIX_TIMESTAMP(spawn_time)) AS seconds
	  FROM	wwiionline.wwii_sortie s INNER JOIN wwiionline.wwii_persona p USING (personaid) INNER JOIN wwiionline.wwii_player pl USING (playerid)
	 WHERE	p.rankid < 3 AND p.branchid = 1 AND spawn_time >= DATE_SUB(NOW(), INTERVAL 24 HOUR)
	 GROUP	BY 1
	HAVING	sorties >= l_min_sorties
	   AND	seconds >= l_min_seconds
	;
END$$

DROP PROCEDURE IF EXISTS `p_feb_11_promo_promote`$$
CREATE DEFINER=`wwiiol`@`localhost` PROCEDURE `p_feb_11_promo_promote` (`i_customerid` INT(11) UNSIGNED)  MODIFIES SQL DATA
    SQL SECURITY INVOKER
BEGIN
	UPDATE	wwiionline.wwii_persona pe INNER JOIN wwiionline.wwii_player pl USING (playerid)
	   SET	pe.rankid = 3
	 WHERE	pl.customerid = i_customerid
	   AND	pe.branchid = 1
	   AND	pe.rankid < 3
	;
END$$

DROP PROCEDURE IF EXISTS `p_get_campaign_status`$$
CREATE DEFINER=`wwiiol`@`localhost` PROCEDURE `p_get_campaign_status` (OUT `o_is_intermission` TINYINT(1) UNSIGNED, OUT `o_campaign_id` INT(11) UNSIGNED, OUT `o_campaign_start` DATETIME)  READS SQL DATA
    SQL SECURITY INVOKER
BEGIN
	SELECT	cf.`value` INTO o_is_intermission
	  FROM	wwiionline.wwii_config cf
	 WHERE	cf.variablename = 'arena.intermission'
	 LIMIT	1
	;
	SELECT	a.`value` INTO o_campaign_id
	  FROM	wwiionline.wwii_arena a
	 WHERE	a.`name` = 'campaign_id'
	 LIMIT	1
	;
	SELECT	FROM_UNIXTIME(a.`value`) INTO o_campaign_start
	  FROM	wwiionline.wwii_arena a
	 WHERE	a.`name` = 'campaign_start'
	 LIMIT	1
	;
END$$

DROP PROCEDURE IF EXISTS `p_get_last_killers`$$
CREATE DEFINER=`wwiiol`@`localhost` PROCEDURE `p_get_last_killers` (`i_callsign` VARCHAR(10) CHARSET ucs2)  READS SQL DATA
    SQL SECURITY INVOKER
BEGIN

    SELECT  k.kill_time
         ,  IF(kp1.callsign IS NOT NULL,CONCAT(kp0.callsign,'/',kp1.callsign),kp0.callsign)
         ,  vv.fullName
         ,  kv.fullName
      FROM  ( wwii.kills k LEFT OUTER JOIN wwiionline.wwii_player kp1 ON (k.killer_player_1 = kp1.playerid) )
            , wwiionline.wwii_player kp0
            , wwiionline.wwii_vehtype vv
            , wwiionline.wwii_vehtype kv
     WHERE  k.victim_player_0 = (SELECT playerid FROM wwiionline.wwii_player WHERE callsign = i_callsign)
			AND k.killer_player_0 = kp0.playerid
			AND k.victim_vehtype_oid = vv.vehtype_oid
			AND k.killer_vehtype_oid = kv.vehtype_oid
     ORDER BY k.kill_time DESC
     LIMIT  5
     ;



END$$

DROP PROCEDURE IF EXISTS `p_get_last_kills`$$
CREATE DEFINER=`wwiiol`@`localhost` PROCEDURE `p_get_last_kills` (`i_callsign` VARCHAR(10) CHARSET ucs2)  READS SQL DATA
    SQL SECURITY INVOKER
BEGIN

    SELECT  k.kill_time AS `kill_time`
		 ,	kv.fullName	AS `killer_veh`
         ,  IF(vp1.callsign IS NOT NULL,CONCAT(vp0.callsign,'/',vp1.callsign),vp0.callsign) AS `victim_crew`
         ,  vv.fullName AS `victim_veh`
      FROM  ( wwii.kills k LEFT OUTER JOIN wwiionline.wwii_player vp1 ON (k.victim_player_1 = vp1.playerid) )
            , wwiionline.wwii_player vp0
            , wwiionline.wwii_vehtype vv
            , wwiionline.wwii_vehtype kv
     WHERE  k.killer_player_0 = (SELECT playerid FROM wwiionline.wwii_player WHERE callsign = i_callsign)
			AND k.victim_player_0 = vp0.playerid
			AND k.killer_vehtype_oid = kv.vehtype_oid
			AND k.victim_vehtype_oid = vv.vehtype_oid
     ORDER BY k.kill_time DESC
     LIMIT  5
     ;

END$$

DROP PROCEDURE IF EXISTS `p_get_persona_data`$$
CREATE DEFINER=`wwiiol`@`localhost` PROCEDURE `p_get_persona_data` (`i_player_id` INT(11) UNSIGNED, `i_country_id` TINYINT(3) UNSIGNED, `i_branch_id` TINYINT(3) UNSIGNED)  READS SQL DATA
    SQL SECURITY INVOKER
BEGIN
		DECLARE l_no_match TINYINT(1) UNSIGNED DEFAULT 0 ;
		DECLARE CONTINUE HANDLER FOR NOT FOUND SET l_no_match = 1 ;

		SELECT	p.personaid 
			 ,	p.countryid
			 ,	p.rankid
			 ,	p.rankpoints
			 ,	pl.locktime
			 ,	pl.lockside
			 ,	auth.f_player_permissions(pl.playerid)
			 ,	pl.player_decal
			 ,	s.squadID
			 ,	s.short_name
			 ,	m.seconds
			 ,	mb.balance
		  FROM	(wwiionline.wwii_player pl
					LEFT OUTER JOIN wwii.minor_usage m ON (pl.playerid = m.playerid AND expires > NOW())
					LEFT OUTER JOIN auth.auth_minute_balance mb ON (pl.customerid = mb.customerid)
				)
				LEFT JOIN wwiionline.wwii_persona p ON (pl.playerid = p.playerid)
					LEFT OUTER JOIN wwiionline.wwii_squads s ON (pl.squadID = s.squadID AND s.disbanded = 0)
		 WHERE	pl.playerid = i_player_id
				AND p.branchid = i_branch_id
		 GROUP	BY p.personaid
		 ORDER	BY IF(p.countryID=i_country_id,0,1) ASC
		;

END$$

DROP PROCEDURE IF EXISTS `p_increase_rank_score`$$
CREATE DEFINER=`wwiiol`@`localhost` PROCEDURE `p_increase_rank_score` (`i_playerid` INT(11) UNSIGNED, `i_country` INT(11) UNSIGNED, `i_branch` INT(11) UNSIGNED, `i_personaid` INT(11) UNSIGNED, `i_rankid` INT(11) UNSIGNED, `i_points` INT(11) UNSIGNED)  MODIFIES SQL DATA
BEGIN

	UPDATE	wwiionline.wwii_persona
	   SET	rankid = i_rankid, rankpoints = i_points
	 WHERE	((personaid = i_personaid) OR (playerid = i_playerid AND countryid = i_country AND branchid = i_branch))
			AND ( rankid < i_rankid OR (rankid = i_rankid AND rankpoints < i_points) )
	;

END$$

DROP PROCEDURE IF EXISTS `p_persona_add_score`$$
CREATE DEFINER=`wwiiol`@`localhost` PROCEDURE `p_persona_add_score` (`forPlayer` INT(11) UNSIGNED, `forPersona` INT(11) UNSIGNED, `pointsScored` INT(11) UNSIGNED, `onSortie` INT(11) UNSIGNED)  MODIFIES SQL DATA
    SQL SECURITY INVOKER
BEGIN
 DECLARE i_persona_points INT(11) unsigned;
 DECLARE i_rank_id  INT unsigned;
 DECLARE i_next_rank_id  INT unsigned;
 DECLARE i_rank_points  INT(11) unsigned;
 DECLARE b_promoted  BOOL DEFAULT false;
 
 DECLARE b_success BOOL DEFAULT true;
 DECLARE CONTINUE HANDLER FOR NOT FOUND SET b_success = false;
 START TRANSACTION ;
 
 SELECT p.rankid, p.rankpoints, r.nextrank, r.pointsrequired
   INTO i_rank_id, i_persona_points, i_next_rank_id, i_rank_points
   FROM wwii_persona p
	INNER JOIN wwii_rank r USING (rankid)
  WHERE p.playerid = forPlayer
	AND p.personaid = forPersona
    FOR UPDATE
 ;
 IF b_success = true AND pointsScored > 0 THEN
   
   SET i_persona_points = i_persona_points + pointsScored;
   
   
   IF i_persona_points >= i_rank_points AND i_next_rank_id > 0 THEN
     SET b_promoted = true;
     SET i_rank_id = i_next_rank_id;
     SET i_persona_points = 0;
     UPDATE wwii_persona p
        SET rankid = i_next_rank_id, rankpoints = i_persona_points
      WHERE personaid = forPersona
     ;
   ELSE
     UPDATE wwii_persona p
	SET rankpoints = i_persona_points
      WHERE personaid = forPersona
	;
   END IF ;
 ELSE
   SET b_success = false ;
 END IF ;

 
 
 
 SELECT forPlayer, forPersona, b_success, b_promoted, i_rank_id, i_persona_points ; 
END$$

