DROP FUNCTION IF EXISTS `f_date_round`$$
CREATE DEFINER=`wwiiol`@`localhost` FUNCTION `f_date_round` (`i_date` DATETIME, `i_seconds` INT(11) UNSIGNED) RETURNS INT(11) UNSIGNED NO SQL
    DETERMINISTIC
BEGIN
	RETURN FLOOR( UNIX_TIMESTAMP(i_date) / i_seconds ) * i_seconds ;
END$$

DROP FUNCTION IF EXISTS `f_date_rounded`$$
CREATE DEFINER=`wwiiol`@`localhost` FUNCTION `f_date_rounded` (`i_date` DATETIME, `i_seconds` INT(11) UNSIGNED) RETURNS DATETIME NO SQL
    DETERMINISTIC
BEGIN
	RETURN FROM_UNIXTIME( FLOOR( UNIX_TIMESTAMP(i_date) / i_seconds ) * i_seconds ) ;
END$$

DROP FUNCTION IF EXISTS `f_hcunit_seq`$$
CREATE DEFINER=`wwiiol`@`localhost` FUNCTION `f_hcunit_seq` (`i_unit_id` SMALLINT(5) UNSIGNED) RETURNS TEXT CHARSET latin1 READS SQL DATA
BEGIN
	DECLARE l_seq TEXT ;
	DECLARE l_unit_id SMALLINT(5) UNSIGNED DEFAULT i_unit_id ;
	DECLARE l_parent_id INT(11) UNSIGNED DEFAULT 0 ;
	DECLARE l_no_record TINYINT(1) UNSIGNED DEFAULT 0 ;

	DECLARE CONTINUE HANDLER FOR NOT FOUND SET l_no_record = 1 ;

	IF l_unit_id = 0 THEN RETURN "" ; END IF ;

	SET l_seq = l_unit_id ;

	REPEAT
		SELECT shu.parent_id INTO l_parent_id FROM wwiionline.strat_hc_units shu WHERE unit_id = l_unit_id ;
		IF l_no_record = 0 AND l_parent_id <> 0 THEN
			SET l_seq = CONCAT(l_parent_id, '-', l_seq) ;
		END IF ;
		SET l_unit_id = l_parent_id ;
	UNTIL l_no_record = 1 OR l_unit_id = 0 END REPEAT ;
	RETURN l_seq ;
END$$

DROP FUNCTION IF EXISTS `f_weapon_spec`$$
CREATE DEFINER=`wwiiol`@`localhost` FUNCTION `f_weapon_spec` (`i_country` INT(11) UNSIGNED, `i_category` INT(11) UNSIGNED, `i_class` INT(11) UNSIGNED, `i_type` INT(11) UNSIGNED) RETURNS INT(11) UNSIGNED NO SQL
    DETERMINISTIC
BEGIN
	RETURN ((i_country << 24) | (i_category << 16) | (i_class << 8) | (i_type)) & 0xffffffff ;
END$$

