--
-- Structure for view `v_player_notes`
--
DROP TABLE IF EXISTS `v_player_notes`;

CREATE ALGORITHM=UNDEFINED DEFINER=`wwiiol`@`66.28.224.141` SQL SECURITY INVOKER VIEW `v_player_notes`  AS  select `note`.`id` AS `id`,`note`.`playerid` AS `playerid`,`note`.`note_type_id` AS `note_type_id`,`note`.`note_at` AS `note_at`,`note`.`note_end` AS `note_end`,`note`.`note_by` AS `note_by`,`note`.`note` AS `note`,`pnt`.`description` AS `description`,if(isnull(`p`.`callsign`),convert(convert('SYSTEM' using ascii) using ucs2),`p`.`callsign`) AS `callsign` from ((`wwiionline`.`player_note_types` `pnt` join `wwiionline`.`player_notes` `note` on((`pnt`.`id` = `note`.`note_type_id`))) left join `wwiionline`.`wwii_player` `p` on((`note`.`note_by` = `p`.`playerid`))) ;

-- --------------------------------------------------------

--
-- Structure for view `v_player_note_counts`
--
DROP TABLE IF EXISTS `v_player_note_counts`;

CREATE ALGORITHM=UNDEFINED DEFINER=`wwiiol`@`66.28.224.141` SQL SECURITY INVOKER VIEW `v_player_note_counts`  AS  select `pl`.`playerid` AS `playerid`,sum(if((`pn`.`note_type_id` = 1),1,0)) AS `comments`,sum(if((`pn`.`note_type_id` = 2),1,0)) AS `bans`,sum(if((`pn`.`note_type_id` = 3),1,0)) AS `warnings` from (`wwiionline`.`wwii_player` `pl` left join `wwiionline`.`player_notes` `pn` on((`pl`.`playerid` = `pn`.`playerid`))) group by `pl`.`playerid` ;

-- --------------------------------------------------------

--
-- Structure for view `v_rank_promotions`
--
DROP TABLE IF EXISTS `v_rank_promotions`;

CREATE ALGORITHM=UNDEFINED DEFINER=`wwiiol`@`66.28.224.141` SQL SECURITY INVOKER VIEW `v_rank_promotions`  AS  select `pl`.`playerid` AS `playerid`,`pl`.`callsign` AS `callsign`,`pe`.`personaid` AS `personaid`,`pe`.`countryid` AS `countryid`,`pe`.`branchid` AS `branchid`,`a`.`recorded` AS `recorded`,`a`.`old_rank` AS `old_rank`,`a`.`new_rank` AS `new_rank` from ((`wwiionline`.`wwii_player` `pl` join `wwiionline`.`wwii_persona` `pe` on((`pl`.`playerid` = `pe`.`playerid`))) join `audit`.`score` `a` on((`pe`.`personaid` = `a`.`personaid`))) where ((`a`.`old_rank` > 0) and (`a`.`old_rank` <> `a`.`new_rank`)) order by `pl`.`playerid`,`pe`.`personaid`,`a`.`recorded` ;

-- --------------------------------------------------------

--
-- Structure for view `v_sortie_crew`
--
DROP TABLE IF EXISTS `v_sortie_crew`;

CREATE ALGORITHM=UNDEFINED DEFINER=`wwiiol`@`66.28.224.141` SQL SECURITY INVOKER VIEW `v_sortie_crew`  AS  select `pilot`.`sortie_id` AS `sortie_id`,`pilot`.`player_id` AS `player_0`,`pilot`.`personaid` AS `persona_0`,if(isnull(`crew`.`player_id`),_latin1'n',_latin1'y') AS `is_multi_crew`,`crew`.`player_id` AS `player_1`,`crew`.`personaid` AS `persona_1` from (`wwiionline`.`wwii_sortie` `pilot` left join `wwiionline`.`wwii_sortie` `crew` on(((`pilot`.`sortie_id` = `crew`.`sortie_id`) and (`crew`.`is_pilot` = 0)))) where (`pilot`.`is_pilot` = 1) ;

-- --------------------------------------------------------

--
-- Structure for view `v_vehicle_vs_vehicle`
--
DROP TABLE IF EXISTS `v_vehicle_vs_vehicle`;

CREATE ALGORITHM=UNDEFINED DEFINER=`wwiiol`@`localhost` SQL SECURITY INVOKER VIEW `v_vehicle_vs_vehicle`  AS  select `kv`.`vehtype_oid` AS `killer`,`vv`.`vehtype_oid` AS `victim`,`k`.`killer_country` AS `killer_country`,`k`.`victim_country` AS `victim_country`,`kv`.`fullName` AS `killer_name`,`vv`.`fullName` AS `victim_name`,count(0) AS `kills` from ((`kills` `k` join `wwiionline`.`wwii_vehtype` `vv`) join `wwiionline`.`wwii_vehtype` `kv`) where ((`k`.`victim_vehtype_oid` = `vv`.`vehtype_oid`) and (`k`.`killer_vehtype_oid` = `kv`.`vehtype_oid`)) group by `kv`.`vehtype_oid`,`vv`.`vehtype_oid` ;
